# Eliminate: y=(x^2+13)/2, z=(y^2-14)/4, then z^2+6x+15=0
def pmul(a, b):
    r = [0] * (len(a) + len(b) - 1)
    for i, u in enumerate(a):
        for j, v in enumerate(b):
            r[i + j] += u * v
    return r

q = [113, 0, 26, 0, 1]            # x^4+26x^2+113, ascending powers
P = pmul(q, q)
