P[0] += 3840                      # degree 8 polynomial (times 256)

def ev(p, x):
    s = 0
    for c in reversed(p):
        s = s * x + c
    return s

n = len(P) - 1
roots = [(0.4 + 0.9j) ** k * 3 for k in range(n)]
for _ in range(2000):
